def min_operations_to_increase_array(n, k, a, b):
    if k == 0:
        # If there are no restrictions, we can increment all elements except the last one
        return max(0, len(a) - 1 - a[-2] + 1)

    # Create a list of indices where elements are not allowed to change
    restricted_indices = set(b - 1 for b in b)

    # Initialize variables
    operations = 0
    current_max = float('-inf')

    for i in range(n):
        if i not in restricted_indices:
            if a[i] <= current_max:
                operations += 1
                current_max += 1
            else:
                current_max = a[i]
        else:
            if a[i] > current_max:
                current_max = a[i]

    return operations if current_max != float('-inf') else -1

