import sys
from typing import List

def min_operations_to_increasing(n: int, k: int, a: List[int], b: List[int]) -> int:
    invalid_indices = {index - 1 for index in b}
    operations = 0
    current_value = 0

    for i in range(n):
        if i not in invalid_indices:
            while a[i] <= current_value:
                a[i] += 1
                operations += 1
            current_value = a[i]

    # Check if the array is increasing
    for i in range(1, n):
        if a[i] <= a[i - 1]:
            return -1

    return operations

